#!/usr/bin/env node
// Offline proof (CI) that a config generated by setup.mjs uploads exactly the committed bundle
// with the expected bindings. Synthetic identifiers only; `wrangler deploy --dry-run` makes no
// account calls. Never reads an installation's own wrangler.toml or deploy/production.json.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { createHash } from 'node:crypto';

const sha = (b) => createHash('sha256').update(b).digest('hex');
const input = {
  workerName: 'ci-library', accountId: 'abcd'.repeat(8), databaseName: 'ci-library-db',
  databaseId: 'abcdef12-1234-4234-8234-123456789abc', bucketName: 'ci-library-blobs', kvNamespaceId: 'bcde'.repeat(8),
  appHost: 'library.ci.test', mcpHost: 'mcp.ci.test', accessTeamDomain: 'ci-team.cloudflareaccess.com',
  accessAudience: 'audience-for-synthetic-ci-check', ownerEmail: 'owner@ci.test', oidcClientId: 'ciSyntheticClient',
  oidcIssuer: 'https://ci-team.cloudflareaccess.com/cdn-cgi/access/sso/oidc/ciSyntheticClient',
  extraRedirectUris: ['https://gateway.ci.test/oauth/callback'],
};
const dir = mkdtempSync(join(tmpdir(), 'al-self-host-upload-'));
const problems = [];
try {
  writeFileSync(join(dir, 'input.json'), JSON.stringify(input));
  const out = join(dir, 'install');
  execFileSync(process.execPath, [resolve('scripts/self-host/setup.mjs'), '--input', join(dir, 'input.json'), '--out', out], { stdio: 'ignore' });
  const upload = join(dir, 'upload');
  const log = execFileSync('npx', ['--no-install', 'wrangler', 'deploy', '--dry-run', '--config', join(out, 'wrangler.json'), '--outdir', upload], {
    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, WRANGLER_SEND_METRICS: 'false', CLOUDFLARE_API_TOKEN: '', CLOUDFLARE_ACCOUNT_ID: '' },
  });
  const files = readdirSync(upload).filter((f) => !f.startsWith('.') && f !== 'README.md');
  if (JSON.stringify(files) !== JSON.stringify(['index.js'])) problems.push(`dry-run produced unexpected modules: ${files.join(', ')}`);
  const want = sha(readFileSync('src/index.js')), got = sha(readFileSync(join(upload, 'index.js')));
  if (want !== got) problems.push(`upload is not byte-identical to src/index.js: ${got} != ${want}`);
  for (const b of ['env.DB (ci-library-db)', `env.OAUTH_KV (${input.kvNamespaceId})`, 'env.BLOBS (ci-library-blobs)', 'env.APP_HOST (', 'env.MCP_HOST (', 'env.OAUTH_EXTRA_REDIRECT_URIS ('])
    if (!log.includes(b)) problems.push(`dry-run binding summary missing ${b}`);
  if (!problems.length) console.log(`self-host config OK: upload == src/index.js (sha256 ${want})`);
} finally { rmSync(dir, { recursive: true, force: true }); }
if (problems.length) { console.error(problems.map((p) => `::error::${p}`).join('\n')); process.exit(1); }
